exercises.tex:
\label{exer 6.1.17} Gerolamo Cardano\index{CARDANO, G.} in his book, \emx {The Gambling Scholar,}
written in the early 1500s, considers the following carnival game.  There are six
dice.  Each of the dice has five blank sides.  The sixth side has a number between
1~and~6---a different number on each die.  The six dice are rolled and the player
wins a prize depending on the total of the numbers which turn up.

\begin{enumerate}
\item Find, as Cardano did, the expected total without finding its distribution.

\item Large prizes were given for large totals with a modest fee to play the game. 
Explain why this could be done.
\end{enumerate}

\label{exer 6.2.10} Prove the following facts about the standard deviation.
\begin{enumerate}
\item $D(X + c) = D(X)$.

\item $D(cX) = |c|D(X)$.
\end{enumerate}

\label{exer 7.1.1} A die is rolled three times.  Find the probability that the sum of
the outcomes is
\begin{enumerate}
\item greater than 9.

\item an odd number.
\end{enumerate}

\label{exer 7.2.1} Let $X$ and $Y$ be independent random variables defined
on the space $\Omega$, with density functions $f_X$~and~$f_Y$, respectively. 
Suppose that $Z = X + Y$.  Find the density $f_Z$ of~$Z$ if
\begin{enumerate}
\item $$f_X(x) = f_Y(x) = \left \{ \begin{array}{ll}
                              1/2,   & \;\mbox{if $-1 \leq x \leq +1,$} \\
                              0,     & \;\mbox{otherwise.}
                  \end{array}
         \right. $$


\item $$f_X(x) = f_Y(x) = \left \{ \begin{array}{ll}
                              1/2,   & \;\mbox{if $3 \leq x \leq 5,$} \\
                              0,     & \;\mbox{otherwise.}
                  \end{array}
         \right. $$


\item $$f_X(x) = \left \{ \begin{array}{ll}
                              1/2,   & \;\mbox{if $-1 \leq x \leq 1,$} \\
                              0,     & \;\mbox{otherwise.}
                  \end{array}
         \right. $$
\smallskip
$$f_Y(x) = \left \{ \begin{array}{ll}
                              1/2,   & \;\mbox{if $3 \leq x \leq 5,$} \\
                              0,     & \;\mbox{otherwise.}
                  \end{array}
         \right. $$
\item What can you say about the set $E = \{\,z : f_Z(z)> 0\,\}$ in each
case?
\end{enumerate}

\label{exer 7.2.2} Suppose again that $Z = X + Y$.  Find $f_Z$ if
\begin{enumerate}
\item $$f_X(x) = f_Y(x) = \left \{ \begin{array}{ll} 
                    x/2, & \mbox{if $0 < x < 2,$} \\
                      0, & \mbox{otherwise}.
                  \end{array}
         \right. $$

\item $$f_X(x) = f_Y(x) = \left \{ \begin{array}{ll} 
                 (1/2)(x - 3), & \mbox{if $3 < x < 5,$} \\
                            0, & \mbox{otherwise}. 
                  \end{array}
         \right. $$

\item $$f_X(x) = \left \{ \begin{array}{ll} 
                       1/2,    & \mbox{if $0 < x < 2,$} \\
                            0, & \mbox{otherwise},
                  \end{array}
         \right. $$
\smallskip
 $$f_Y(x) = \left \{ \begin{array}{ll} 
                          x/2, & \mbox{if $0 < x < 2,$} \\
                            0, & \mbox{otherwise}.
                  \end{array}
         \right. $$
\item What can you say about the set $E = \{\,z : f_Z(z)> 0\,\}$ in each
case?
\end{enumerate}

\label{exer 7.2.3} Let $X$, $Y$, and $Z$ be independent random variables
with 
$$f_X(x) = f_Y(x) = f_Z(x)  = \left \{ \begin{array}{ll}
                              1,     & \mbox{if $0 < x < 1,$} \\
                              0,     & \mbox{otherwise.}
                  \end{array}
         \right. $$
\noindent Suppose that $W = X + Y + Z$.  Find $f_W$ directly, and compare your answer
with that given by the formula in Example~\ref{exam 7.12}.   \emx {Hint}:  See 
Example~\ref{exam 7.6}.

\label{exer 7.2.3.5} Suppose that $X$ and $Y$ are independent and $Z = X + Y$.  Find
$f_Z$ if

\begin{enumerate}
\item $$f_X(x) = \left \{ \begin{array}{ll}
                              \lambda e^{-\lambda x}, & \mbox{if $x > 0,$} \\
                               0,                     & \mbox{otherwise.}
                  \end{array}
         \right. $$
\smallskip
$$f_Y(x) = \left \{ \begin{array}{ll}
                              \mu e^{-\mu x}, & \mbox{if $x > 0,$} \\
                              0,              & \mbox{otherwise.}
                  \end{array}
         \right. $$
\item $$\ \ \ f_X(x) = \left \{ \begin{array}{ll}
                              \lambda e^{-\lambda x}, & \mbox{if $x > 0,$} \\
                              0,                      & \mbox{otherwise.}
                  \end{array}
         \right. $$

\smallskip
$$f_Y(x) = \left \{ \begin{array}{ll}
                    1, & \mbox{if $0 < x < 1,$} \\
                    0, & \mbox{otherwise.}
                  \end{array}
         \right. $$
\end{enumerate}

\label{exer 7.2.100} Suppose again that $Z = X + Y$.  Find $f_Z$ if
\begin{eqnarray*}
f_X(x) &=& \frac 1{\sqrt{2\pi}\sigma_1} e^{-(x - \mu_1)^2/2\sigma_1^2} \\
f_Y(x) &=& \frac 1{\sqrt{2\pi}\sigma_2} e^{-(x - \mu_2)^2/2\sigma_2^2}\ .
\end{eqnarray*}

